input.content:
{
  "title": "S4-b28aa5b6 Web logs",
  "panels": [
    {
      "type": "vis",
      "grid": { "x": 0, "y": 0, "w": 24, "h": 10 },
      "config": {
        "type": "xy",
        "title": "Requests over time",
        "data_source": {
          "type": "data_view_spec",
          "index_pattern": "kibana_sample_data_logs",
          "time_field": "timestamp"
        },
        "ignore_global_filters": false,
        "sampling": 1,
        "layers": [
          {
            "type": "line",
            "data_source": {
              "type": "esql",
              "query": "FROM kibana_sample_data_logs | STATS count = COUNT() BY BUCKET(@timestamp, 75, ?_tstart, ?_tend)"
            },
            "ignore_global_filters": false,
            "sampling": 1,
            "x": { "column": "BUCKET(@timestamp, 75, ?_tstart, ?_tend)" },
            "y": [{ "axis_id": "y", "column": "count" }]
          }
        ]
      }
    },
    {
      "type": "vis",
      "grid": { "x": 0, "y": 10, "w": 24, "h": 12 },
      "config": {
        "type": "pie",
        "title": "Requests by response code",
        "data_source": {
          "type": "data_view_spec",
          "index_pattern": "kibana_sample_data_logs",
          "time_field": "timestamp"
        },
        "ignore_global_filters": false,
        "sampling": 1,
        "metrics": [{ "operation": "count", "empty_as_null": false }],
        "group_by": [
          {
            "operation": "terms",
            "fields": ["response.keyword"],
            "limit": 10
          }
        ],
        "styling": {
          "donut_hole": "m",
          "labels": { "position": "outside", "visible": true },
          "values": { "mode": "percentage", "visible": true }
        }
      }
    }
  ]
}

